:root {
  --cream: #f2e8d5;
  --tan: #d9c8a3;
  --bark: #7a5c38;
  --river: #3a6b7e;
  --river-light: #c0d9e3;
  --ink: #2b1f0e;
  --muted: #8a7355;
  --accent: #c4552a;
  --stub-bg: #3a6b7e;
  --stub-text: #f2e8d5;
  --border-dash: #b0956a;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
}

.ticket {
  background-color: var(--cream);
  border: 2px solid var(--bark);
  border-radius: 6px;
  width: 480px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.ticket-header {
  background-color: var(--river);
  color: var(--cream);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 16px;
}

.route-label {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 3px;
}

.ticket-number {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--river-light);
}

.ticket-body {
  padding: 16px 16px 12px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.route-row {
  display: flex;
  align-items: center;
  gap: 10px;
}

.terminal {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
}

.terminal-name {
  font-size: 20px;
  font-weight: 700;
  color: var(--ink);
  line-height: 1;
}

.terminal-sub {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 2px;
  color: var(--muted);
}

.route-line {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border-top: 2px dashed var(--border-dash);
  position: relative;
  top: -4px;
}

.arrow-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background-color: var(--bark);
  flex-shrink: 0;
  position: relative;
  top: -1px;
}

.ferry-icon {
  font-size: 20px;
  line-height: 1;
  position: relative;
  top: -1px;
}

.details-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  border-top: 1px solid var(--tan);
  padding-top: 12px;
}

.detail-block {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.detail-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--muted);
  text-transform: uppercase;
}

.detail-value {
  font-size: 13px;
  font-weight: 700;
  color: var(--ink);
}

.ticket-footer {
  background-color: var(--tan);
  border-top: 2px dashed var(--border-dash);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 0 10px 16px;
  gap: 0;
}

.footer-left {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.company {
  font-size: 12px;
  font-weight: 700;
  color: var(--bark);
  letter-spacing: 1px;
}

.note {
  font-size: 10px;
  color: var(--muted);
}

.stub {
  background-color: var(--stub-bg);
  color: var(--stub-text);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 10px 16px;
  gap: 4px;
  align-self: stretch;
}

.stub-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 3px;
  color: var(--river-light);
}

.stub-num {
  font-size: 11px;
  font-weight: 700;
  color: var(--stub-text);
  letter-spacing: 1px;
}
